```js
// Counter
const count = new Map();
for (const x of arr) count.set(x, (count.get(x) ?? 0) + 1);

// Two Sum (seen-so-far)
function twoSum(nums, target) {
  const seen = new Map();                       // value -> index
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}

// Sliding window, fixed size k
function bestWindow(arr, k) {
  let cur = 0;
  for (let i = 0; i < k; i++) cur += arr[i];
  let best = cur;
  for (let i = k; i < arr.length; i++) {
    cur += arr[i] - arr[i - k];
    best = Math.max(best, cur);
  }
  return best;
}

// Lower bound binary search: first index with arr[i] >= x
function lowerBound(arr, x) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] < x) lo = mid + 1; else hi = mid;
  }
  return lo;
}

// Queue with a head pointer (BFS)
const queue = [start]; let head = 0;
while (head < queue.length) {
  const node = queue[head++];
  for (const next of graph.get(node) ?? []) {
    if (!visited.has(next)) { visited.add(next); queue.push(next); }
  }
}

// Valid brackets (stack)
function valid(s) {
  const pairs = { ")": "(", "]": "[", "}": "{" };
  const stack = [];
  for (const ch of s) {
    if (ch in pairs) { if (stack.pop() !== pairs[ch]) return false; }
    else stack.push(ch);
  }
  return stack.length === 0;
}
```
