questions.a:
Two stacks: push to `inbox`; for pop/peek, if `outbox` is empty, move everything from inbox to outbox (reversing order). Amortised O(1).
```python
class MyQueue:
    def __init__(self): self.i, self.o = [], []
    def push(self, x): self.i.append(x)
    def _move(self):
        if not self.o:
            while self.i: self.o.append(self.i.pop())
    def pop(self): self._move(); return self.o.pop()
    def peek(self): self._move(); return self.o[-1]
    def empty(self): return not self.i and not self.o
```

Monotonic deque of indices with decreasing values; the front is the max of the current window. O(n).
```python
from collections import deque
def max_window(nums, k):
    dq, out = deque(), []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x: dq.pop()
        dq.append(i)
        if dq[0] <= i - k: dq.popleft()
        if i >= k - 1: out.append(nums[dq[0]])
    return out
```

Max-heap (push negatives): smash the two heaviest, push back the difference. O(n log n).
```python
import heapq
def last_stone(stones):
    h = [-s for s in stones]; heapq.heapify(h)
    while len(h) > 1:
        a, b = -heapq.heappop(h), -heapq.heappop(h)
        if a != b: heapq.heappush(h, -(a - b))
    return -h[0] if h else 0
```

Two heaps: a max-heap for the lower half, a min-heap for the upper half, kept balanced. Add O(log n), median O(1).
```python
import heapq
class MedianFinder:
    def __init__(self): self.lo, self.hi = [], []   # lo is a max-heap (negated)
    def addNum(self, x):
        heapq.heappush(self.lo, -x)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo): heapq.heappush(self.lo, -heapq.heappop(self.hi))
    def findMedian(self):
        if len(self.lo) > len(self.hi): return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2
```

