For each unvisited land cell, flood-fill (DFS/BFS) the whole island and count +1. O(rows x cols).
```python
def num_islands(g):
    R, C, count = len(g), len(g[0]), 0
    def sink(r, c):
        if 0 <= r < R and 0 <= c < C and g[r][c] == "1":
            g[r][c] = "0"
            sink(r+1, c); sink(r-1, c); sink(r, c+1); sink(r, c-1)
    for r in range(R):
        for c in range(C):
            if g[r][c] == "1": count += 1; sink(r, c)
    return count
```
Very large grids: use an iterative BFS to avoid Python's recursion limit.

Multi-source BFS: start with all rotten oranges in the queue, spread one level per minute, count fresh ones left.
```python
from collections import deque
def oranges(g):
    R, C = len(g), len(g[0])
    q = deque((r, c) for r in range(R) for c in range(C) if g[r][c] == 2)
    fresh = sum(row.count(1) for row in g); minutes = 0
    while q and fresh:
        for _ in range(len(q)):
            r, c = q.popleft()
            for nr, nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 1:
                    g[nr][nc] = 2; fresh -= 1; q.append((nr, nc))
        minutes += 1
    return -1 if fresh else minutes
```

Backtracking: choose an unused element, recurse, un-choose. n! results.
```python
def permute(nums):
    res, cur, used = [], [], [False] * len(nums)
    def go():
        if len(cur) == len(nums): res.append(cur[:]); return
        for i, x in enumerate(nums):
            if not used[i]:
                used[i] = True; cur.append(x); go(); cur.pop(); used[i] = False
    go(); return res
```
`itertools.permutations(nums)` if you're allowed to use it.

Backtracking where each number can be reused; start the loop from the current index to avoid duplicate combos.
```python
def comb_sum(cands, target):
    res, cur = [], []
    def go(start, remain):
        if remain == 0: res.append(cur[:]); return
        for i in range(start, len(cands)):
            if cands[i] <= remain:
                cur.append(cands[i]); go(i, remain - cands[i]); cur.pop()
    cands.sort(); go(0, target); return res
```

